// Renders every conversation of tests/golden/template_cases.json with
// RenderPrompt and compares the result with the prompt the official Jinja
// template renders for it (generated by tools/gen_template_goldens.py).
//
// Usage: flint_tool_template_test tests/golden/template_cases.json

#include <cstddef>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include <gufo/ext/json.hpp>

#include "src/chat_template.hpp"

namespace {

namespace json = ::gufo::json;
using gufo::models::flint::ChatMessage;
using gufo::models::flint::ChatTool;
using gufo::models::flint::ToolArgument;
using gufo::models::flint::ToolCall;

std::string ReadFile(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  if (!in)
    throw std::runtime_error("cannot read " + path);
  std::ostringstream out;
  out << in.rdbuf();
  return out.str();
}

ChatMessage ToMessage(const json::Value& value) {
  ChatMessage message;
  message.role = value.member_str("role");
  message.content = value.member_str("content");
  message.reasoning_content = value.member_str("reasoning_content");
  if (const json::Value* calls = value.find("tool_calls")) {
    for (const auto& item : calls->items()) {
      ToolCall call;
      call.name = item.member_str("name");
      if (const json::Value* arguments = item.find("arguments")) {
        for (const auto& [key, argument] : arguments->members()) {
          if (argument.is_string())
            call.arguments.push_back({key, argument.str(), true});
          else
            call.arguments.push_back(
                {key, argument.dump(), false});
        }
      }
      message.tool_calls.push_back(std::move(call));
    }
  }
  return message;
}

std::size_t FirstDifference(const std::string& a, const std::string& b) {
  std::size_t i = 0;
  while (i < a.size() && i < b.size() && a[i] == b[i])
    ++i;
  return i;
}

std::string Excerpt(const std::string& text, std::size_t at) {
  const std::size_t from = at > 40 ? at - 40 : 0;
  return text.substr(from, 100);
}

}  // namespace

int main(int argc, char** argv) {
  if (argc != 2) {
    std::cerr << "usage: flint_tool_template_test CASES.json\n";
    return 2;
  }
  const json::Value cases = json::parse(ReadFile(argv[1]));
  int failures = 0;
  for (const auto& item : cases.items()) {
    const std::string name = item.member_str("name");
    std::vector<ChatMessage> messages;
    for (const auto& m : item.find("messages")->items())
      messages.push_back(ToMessage(m));
    std::vector<ChatTool> tools;
    for (const auto& t : item.find("tools")->items()) {
      ChatTool tool;
      tool.definition_json = t.dump();
      tools.push_back(std::move(tool));
    }
    const std::string expected = item.member_str("expected");
    const std::string got =
        gufo::models::flint::RenderPrompt(messages, tools);
    // A definition that only has name, description and parameters is rebuilt
    // identically when the caller gives those three fields instead.
    std::vector<ChatTool> rebuilt;
    bool rebuildable = true;
    for (const auto& t : item.find("tools")->items()) {
      for (const auto& [key, ignored] : t.members()) {
        if (key != "name" && key != "description" && key != "parameters")
          rebuildable = false;
      }
      ChatTool tool;
      tool.name = t.member_str("name");
      tool.description = t.member_str("description");
      if (const json::Value* parameters = t.find("parameters"))
        tool.parameters_json = parameters->dump();
      rebuilt.push_back(std::move(tool));
    }
    if (rebuildable && gufo::models::flint::RenderPrompt(messages, rebuilt) != expected) {
      ++failures;
      std::cout << "FAIL  " << name << " (tool definition rebuilt from fields)\n";
    }
    if (got == expected) {
      std::cout << "ok    " << name << "\n";
      continue;
    }
    ++failures;
    const std::size_t at = FirstDifference(got, expected);
    std::cout << "FAIL  " << name << " (first difference at byte " << at
              << ")\n  expected: " << Excerpt(expected, at)
              << "\n  got     : " << Excerpt(got, at) << "\n";
  }
  std::cout << (failures == 0 ? "all passed" : "failures") << ": "
            << cases.size() - failures << "/" << cases.size() << "\n";
  return failures == 0 ? 0 : 1;
}
